args.cmd:
Set-Content -Path .\_test_local.ps1 -Encoding UTF8 @'
$staging = "http://127.0.0.1:4010/v1/chat/completions"
$results = @()
foreach ($sysChars in @(200, 2000, 8000, 25000, 45000)) {
  $sysText = "You are a senior code reviewer. " * [Math]::Max(1, [int]($sysChars/30))
  $userText = "Reply with one short sentence."
  $body = @{
    model = "qwen3.6-35b-a3b-fp8"
    messages = @(
      @{role="system"; content=$sysText.Substring(0,[Math]::Min($sysText.Length,$sysChars))},
      @{role="user"; content=$userText}
    )
    max_tokens = 24
    temperature = 0
  } | ConvertTo-Json -Depth 8
  Invoke-WebRequest -Uri $staging -Method POST -ContentType "application/json" -Body $body -TimeoutSec 90 -UseBasicParsing -ErrorAction SilentlyContinue | Out-Null
  $sw = [System.Diagnostics.Stopwatch]::StartNew()
  try {
    $r = Invoke-WebRequest -Uri $staging -Method POST -ContentType "application/json" -Body $body -TimeoutSec 120 -UseBasicParsing -ErrorAction Stop
    $sw.Stop()
    $j = $r.Content | ConvertFrom-Json
    $pt = $j.usage.prompt_tokens
    $ct = $j.usage.completion_tokens
    $routed = if ($j.model -match "Qwen") { "LOCAL" } else { "OTHER: $($j.model)" }
    $results += [PSCustomObject]@{SysChars=$sysChars; Wall_ms=[int]$sw.ElapsedMilliseconds; Prompt_tok=$pt; Completion_tok=$ct; RoutedTo=$routed; Finish=$j.choices[0].finish_reason}
    Write-Host ("[sys={0}] routed={1} prompt={2}`t out={3}`t wall={4}ms" -f $sysChars, $routed, $pt, $ct, $results[-1].Wall_ms)
  } catch {
    $sw.Stop()
    $code = $_.Exception.Response.StatusCode.value__
    $results += [PSCustomObject]@{SysChars=$sysChars; Wall_ms=[int]$sw.ElapsedMilliseconds; Prompt_tok="-"; Completion_tok="-"; RoutedTo="HTTP $code"; Finish=$_}
    Write-Host ("[sys={0}] HTTP {1}: {2}" -f $sysChars, $code, $_.Exception.Message.Split([char]10)[0])
  }
}
$results | Format-Table -AutoSize | Out-String
'@
powershell -ExecutionPolicy Bypass -File .\_test_local.ps1

