import re, json
from pathlib import Path
out={}
for f in sorted(Path('reports/jinjiang-r20/blindtest_packs').glob('*.md')):
    text=f.read_text(encoding='utf8'); chunks=re.split(r'(?m)^## ',text)
    rows={}
    for chunk in chunks[1:]:
        lines=chunk.splitlines(); ch=lines[0].strip(); body='\n'.join(lines[1:]); body=re.sub(r'\n---\s*\n?\$','',body)
        paras=[p.strip() for p in body.split('\n\n') if p.strip() and p.strip()!='---']
        if not paras: continue
        rows[ch]={'first':paras[0][:120],'mid':paras[len(paras)//2][:120],'last':paras[-1][:200]}
    out[f.stem]=rows
Path('reports/jinjiang-r20/blindtest-summaries.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print('saved',sum(len(v) for v in out.values()),'chapters across',len(out),'packs')
"

