args.chars:
def load_stub_set():
    """读 _STUB_MANIFEST.json，返回 stub 文件名集合。文件不存在则返回空集。

    兼容两种格式：
      - files: [{"filename": "..."}, ...]   （旧 dict 列表）
      - files: ["...", ...]                  （新字符串列表，本轮 P0 落地后采用）
    也会读 chapter_numbers，配合 glob 匹配文件名。
    """
    if not os.path.isfile(STUB_MANIFEST):
        return set()
    try:
        with open(STUB_MANIFEST, encoding="utf-8") as fh:
            data = json.load(fh)
        out = set()
        for entry in data.get("files", []):
            if isinstance(entry, dict):
                out.add(entry.get("filename", ""))
            elif isinstance(entry, str):
                out.add(entry)
        # 同时把 chapter_numbers 展开成文件名（如 "ch251-..." / "251-..."）
        for n in data.get("chapter_numbers", []):
            out.add(f"{n:03d}-")  # 模糊匹配前缀会在主循环里过滤
        return {x for x in out if x}
    except Exception:
        return set()

