  @{ name='P2_powershell';prompt='On Windows PowerShell, list all .log files under C:\Users\stanc\github that contain the word "VERIFIED_PASS", showing only the first 5 matches with line numbers. Reply with only the command in one fenced PowerShell block, no prose.' },
  @{ name='P3_toolargs';  prompt='Emit a single tool call to function `search_repo` with args {"query": "timeout", "path": "C:\\repo\\src", "max_results": 10, "recursive": true}. Output only the JSON tool call.' }
)

$summary = New-Object System.Collections.Generic.List[Object]

foreach ($p in $prompts) {
  Write-Host ""
  Write-Host ("###### {0} ######" -f $p.name)

  foreach ($mode in @(
    @{ key='A_M3_single';   model='minimax/minimax-m3'; extra=$null },
    @{ key='B_M3_turbo';    model='minimax/minimax-m3'; extra='cheap_plus_turbo' },
