    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    try {
      $resp = Invoke-RestMethod -Method Post -Uri $base -Headers $h -ContentType 'application/json' -Body $body -TimeoutSec 90
      $sw.Stop()
      $content = $resp.choices[0].message.content
      $usage = $resp.usage
      $ok = $true
      $err = $null
    } catch {
      $sw.Stop()
      $content = $null
      $usage = $null
      $ok = $false
      $err = $_.Exception.Message
    }

    $rec = [pscustomobject]@{
      prompt   = $p.name
      run      = $mode.key
      model    = $mode.model
      cheap_plus = $mode.extra
      latency_s = [math]::Round($sw.Elapsed.TotalSeconds, 2)
      ok       = $ok
      prompt_tokens   = if ($usage) { $usage.prompt_tokens }   else { 0 }
      completion_tokens = if ($usage) { $usage.completion_tokens } else { 0 }
      total_tokens = if ($usage) { $usage.total_tokens }   else { 0 }
      error    = $err
      content  = $content
    }
