    Write-Host ("--- {0} | {1} | {2:F2}s | p={3} c={4} t={5} ---" -f $p.name, $mode.key, $rec.latency_s, $rec.prompt_tokens, $rec.completion_tokens, $rec.total_tokens)
    if ($ok) {
      $snippet = ($content -replace "`r`n"," ")
      if ($snippet.Length -gt 600) { $snippet = $snippet.Substring(0,600) + '...[truncated]' }
      Write-Host $snippet
    } else {
      Write-Host "ERROR: $err"
    }
  }
}

