import pathlib
p = pathlib.Path('engine/prose_lint.py')
t = p.read_text(encoding='utf-8')
# Insert placeholder-hook check in strict mode after self_claim block (after line 321)
old = '''          if \"self_claim\" in echo_hits:
              errors.append(
                  f\"自我承担回环：{echo_hits['self_claim']} 处「我/他/她自己」后置解释，\"
                  \"删掉口号式自证，让选择用代价、物件或他人反应落地\"
              )
      # WARN 级'''
new = '''          if \"self_claim\" in echo_hits:
              errors.append(
                  f\"自我承担回环：{echo_hits['self_claim']} 处「我/他/她自己」后置解释，\"
                  \"删掉口号式自证，让选择用代价、物件或他人反应落地\"
              )
          # §七.1 第三道墙——钩子占位。\"下一章切下批头一章\"是机器循环留的
          # 假钩子，不在正文里、也不能被读者 grep 到。任何用占位钩子的章节，
          # 即使正文过了，也算未上线。
          _fm = re.match(r\"^---\\s*\\n(.*?)\\n---\", text, re.S)
          if _fm:
              try:
                  import yaml as _y
                  _fmd = _y.safe_load(_fm.group(1)) or {}
              except Exception:
                  _fmd = {}
              _hook = str(_fmd.get(\"hook\", \"\")).strip()
              _body = body_of(text)
              if \"下一章切下批头\" in _hook or \"下回再说\" in _hook or \"留待下回\" in _hook:
                  errors.append(
                      \"§七.1 占位钩子：hook 字段含「下一章切下批头/下回再说/留待下回」，\"
                      \"按晋江腔把钩子换成正文真实出现过的物件/动作/对白\"
                  )
              elif _hook and len(_hook) > 8:
                  # 钩子至少要在正文中能被找到一段
                  _anchor = _hook[:8].strip(\"。.?!！？\\n\")
                  if _anchor and _anchor not in _body:
                      errors.append(
                          f\"§七.1 钩子不兑现：hook 字段「{_anchor}…」在正文中未出现，\"
                          \"晋江读者读到钩子却追不到具体物件/动作，下回就跑\"
                      )
      # WARN 级'''
if old in t:
    t2 = t.replace(old, new)
    p.write_text(t2, encoding='utf-8')
    print('inserted')
else:
    print('not found')
"","shell":"powershell","workdir":"C:\Users\stanc\github\open-souls"},"tool":"exec_command"}

