args.cmd:
Write-Host '--- search token_stats.jsonl history for gemini.channel=antigravity ---'
$ts = 'logs\token_stats.json'
if (Test-Path $ts) {
  Write-Host "size: $((Get-Item $ts).Length)"
  # Token stats records look like query entries, not usage snapshots. Search anyway.
  Select-String -Path $ts -Pattern 'channel' | Select-Object -First 10
} 
Write-Host '--- search codex_router.log for antigravity / gemini / channel ---'
$log = 'logs\codex_router.log'
if (Test-Path $log) {
  Write-Host "size: $((Get-Item $log).Length)"
  Select-String -Path $log -Pattern 'channel=|antigravity' | Select-Object -First 30 | ForEach-Object { "$($_.LineNumber): $($_.Line.Substring(0,[Math]::Min(200,$_.Line.Length)))" }
}
Write-Host '--- antigravity bridge history ---'
Get-Content 'logs\bridge_daemon.log' -Tail 50
Get-Content 'logs\antigravity_bridge.log' -Tail 20

